function summarizeSetAtomValuePayload(value: unknown) {
  if (value === undefined) {
    return 'undefined';
  }
  if (value === null) {
    return 'null';
  }
  if (Array.isArray(value)) {
    return `array(len=${value.length})`;
  }
  const valueType = typeof value;
  if (valueType === 'string') {
    return `string(len=${(value as string).length})`;
  }
  if (
    valueType === 'number' ||
    valueType === 'boolean' ||
    valueType === 'bigint'
  ) {
    return `${valueType}(${String(value)})`;
  }
  if (valueType === 'object') {
    const objectValue = value as Record<string, unknown>;
    const keys = Object.keys(objectValue);
    const previewKeys = keys.slice(0, 12);
    const undefinedKeys = previewKeys.filter(
      (key) => objectValue[key] === undefined,
    );
    return [
      `object(keys=${keys.length})`,
      `previewKeys=${previewKeys.join('|') || 'none'}`,
      `undefinedPreviewKeys=${undefinedKeys.join('|') || 'none'}`,
    ].join(', ');
  }
  return valueType;
}

const PASSWORD_VERIFY_STATUS_VALUES = new Set(
  Object.values(EPasswordVerifyStatus),
);

const TRAVEL_MODE_CONTEXT_STORE_KEYS = new Set([
  'accountSelector@home',
  'accountSelector@swap',
  'perps',
  'swap',
]);

const TRAVEL_MODE_RESETTABLE_PERPS_ATOMS = new Set<EAtomNames>([
  EAtomNames.perpsActiveAssetCtxAtom,
  EAtomNames.perpsActiveAssetCtxDisplayAtom,
  EAtomNames.perpsActiveAssetDataAtom,
  EAtomNames.spotActiveAssetCtxAtom,
]);

function isPlainRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value && typeof value === 'object' && !Array.isArray(value));
}

function buildTravelModeContextStoreMapView(
  value: unknown,
): Record<string, unknown> {
  if (!isPlainRecord(value)) {
    return {};
  }

  const result: Record<string, unknown> = {};
  TRAVEL_MODE_CONTEXT_STORE_KEYS.forEach((key) => {
    const item = value[key];
    if (!isPlainRecord(item)) {
      return;
    }
    const count = item.count;
    if (typeof count !== 'number' || !Number.isFinite(count) || count <= 0) {
      return;
    }
    const normalizedCount = Math.min(Math.trunc(count), 100);
    if (key === 'perps' || key === 'swap') {
      if (item.storeName !== key) {
        return;
      }
      result[key] = { storeName: key, count: normalizedCount };
      return;
    }

    if (item.storeName !== 'accountSelector') {
      return;
    }
    const accountSelectorInfo = item.accountSelectorInfo;
    if (!isPlainRecord(accountSelectorInfo)) {
      return;
    }
    const sceneName = key === 'accountSelector@home' ? 'home' : 'swap';
    if (
      accountSelectorInfo.sceneName !== sceneName ||
      (accountSelectorInfo.sceneUrl !== undefined &&
        accountSelectorInfo.sceneUrl !== '')
    ) {
      return;
    }
    const enabledNum = Array.isArray(accountSelectorInfo.enabledNum)
      ? [
          ...new Set(
            accountSelectorInfo.enabledNum.filter(
              (num): num is number => num === 0 || num === 1,
            ),
          ),
        ].toSorted()
      : [];
    if (!enabledNum.length) {
      return;
    }
    result[key] = {
      storeName: 'accountSelector',
      accountSelectorInfo: {
        sceneName,
        sceneUrl: '',
        enabledNum,
      },
      count: normalizedCount,
    };
  });
  return result;
}

function buildTravelModePerpsOrderBookOptionsView(value: unknown) {
  if (value === undefined) {
    return undefined;
  }
  if (!isPlainRecord(value)) {
    return undefined;
  }

  const coin = value.coin;
  const assetId = value.assetId;
  const nSigFigs = value.nSigFigs;
  const mantissa = value.mantissa;
  if (
    typeof coin !== 'string' ||
    coin.length === 0 ||
    coin.length > 128 ||
    (assetId !== undefined &&
      (typeof assetId !== 'number' ||
        !Number.isSafeInteger(assetId) ||
        assetId < 0)) ||
    (nSigFigs !== undefined &&
      nSigFigs !== null &&
      ![2, 3, 4, 5].includes(nSigFigs as number)) ||
    (mantissa !== undefined &&
      mantissa !== null &&
      mantissa !== 2 &&
      mantissa !== 5)
  ) {
    return undefined;
  }

  return {
    coin,
    assetId,
    nSigFigs,
    mantissa,
  };
}

function buildTravelModeTradingModeView(value: unknown) {
  return value === 'spot' ? 'spot' : 'perp';
}

async function buildTravelModePasswordRuntimeState({
  currentValue,
  proposedValue,
}: {
  currentValue: IPasswordAtom;
  proposedValue: unknown;
}): Promise<IPasswordAtom> {
  const proposedStatus = (
    proposedValue as Partial<IPasswordAtom> | null | undefined
  )?.passwordVerifyStatus;
  if (
    !proposedStatus ||
    !PASSWORD_VERIFY_STATUS_VALUES.has(proposedStatus.value) ||
    (proposedStatus.message !== undefined &&
      typeof proposedStatus.message !== 'string')
  ) {
    return rejectTravelModeUnknownError();
  }
  return {
    ...currentValue,
    passwordVerifyStatus: {
      value: proposedStatus.value,
      ...(proposedStatus.message === undefined
        ? undefined
        : { message: proposedStatus.message }),
    },
  };
}

const TRAVEL_MODE_READABLE_ATOMS = new Set<EAtomNames>([
  EAtomNames.currencyPersistAtom,
  EAtomNames.jotaiContextStoreMapAtom,
  EAtomNames.passwordAtom,
  EAtomNames.passwordPersistAtom,
  EAtomNames.passwordPersistManualLockStateAtom,
  EAtomNames.perpsActiveOrderBookOptionsAtom,
  EAtomNames.settingsPersistAtom,
  EAtomNames.tradingModeAtom,
]);

const TRAVEL_MODE_WRITABLE_ATOMS = new Set<EAtomNames>([
  EAtomNames.jotaiContextStoreMapAtom,
  EAtomNames.passwordAtom,
  EAtomNames.passwordPersistAtom,
  EAtomNames.perpsActiveOrderBookOptionsAtom,
  ...TRAVEL_MODE_RESETTABLE_PERPS_ATOMS,
  EAtomNames.settingsPersistAtom,
  EAtomNames.tradingModeAtom,
]);

async function buildTravelModeAtomState(
  atomName: EAtomNames,
  atomValue: unknown,
): Promise<unknown> {
  switch (atomName) {
    case EAtomNames.currencyPersistAtom:
      return buildTravelModeCurrencyReferenceView({
        initialValue: currencyPersistAtomInitialValue,
        persistedValue: atomValue,
      });
    case EAtomNames.jotaiContextStoreMapAtom:
      return buildTravelModeContextStoreMapView(atomValue);
    case EAtomNames.passwordPersistAtom:
      return buildTravelModePasswordPersistView({
        initialValue: passwordAtomInitialValue,
        persistedValue: atomValue,
      });
    case EAtomNames.passwordAtom: {
      const passwordState = atomValue as Partial<IPasswordAtom>;
      const passwordVerifyStatus = passwordState.passwordVerifyStatus;
      return {
        unLock: passwordState.unLock === true,
        passwordVerifyStatus:
          passwordVerifyStatus &&
          PASSWORD_VERIFY_STATUS_VALUES.has(passwordVerifyStatus.value) &&
          (passwordVerifyStatus.message === undefined ||
            typeof passwordVerifyStatus.message === 'string')
            ? passwordVerifyStatus
            : { value: EPasswordVerifyStatus.DEFAULT },
      } satisfies IPasswordAtom;
    }
    case EAtomNames.passwordPersistManualLockStateAtom:
      return buildTravelModeManualLockPersistView({
        initialValue: { manualLocking: false },
        persistedValue: atomValue,
      });
    case EAtomNames.perpsActiveOrderBookOptionsAtom:
      return buildTravelModePerpsOrderBookOptionsView(atomValue);
    case EAtomNames.settingsPersistAtom:
      return buildTravelModeSettingsPersistView({
        initialValue: settingsAtomInitialValue,
        persistedValue: atomValue,
      });
    case EAtomNames.tradingModeAtom:
      return buildTravelModeTradingModeView(atomValue);
    default:
      return rejectTravelModeUnknownError();
  }
}

const ASYNC_STORAGE_FORWARDER_BG_LOG_PREFIX = '[AsyncStorageForwarder][BG]';
const ASYNC_STORAGE_FORWARDER_COMPLETED_REQUEST_LIMIT = 512;

function stringifyAsyncStorageForwarderBgLogValue(value: unknown) {
  try {
    return JSON.stringify(value);
  } catch (error) {
    return JSON.stringify({
      stringifyError: (error as Error)?.message || 'unknown',
    });
  }
}

function asyncStorageForwarderBgLog(label: string, value?: unknown) {
  try {
    const valueText =
      value === undefined
        ? ''
        : ` ${stringifyAsyncStorageForwarderBgLogValue(value)}`;
    NativeLogger.write(
      LogLevel.Info,
      `${ASYNC_STORAGE_FORWARDER_BG_LOG_PREFIX} ${label}${valueText}`,
    );
  } catch {
    /* noop */
  }
}

function getAsyncStorageWriteRequestSummary(
  request: IAsyncStorageWriteRequest,
) {
  const { requestId } = request;
  switch (request.method) {
    case 'clear':
      return { method: request.method, requestId };
    case 'multiRemove':
      return {
        method: request.method,
        requestId,
        keyCount: request.args[0].length,
      };
    case 'multiSet':
    case 'multiMerge':
      return {
        method: request.method,
        requestId,
        pairCount: request.args[0].length,
      };
    default: {
      const unsupportedRequest: never = request;
      return { method: String(unsupportedRequest) };
    }
  }
}

function getAsyncStorageForwarderSharedStore() {
  return getBackgroundThreadSharedStore();
}

@backgroundClass()
class BackgroundApiBase implements IBackgroundApiBridge {
  private static readonly PENDING_BRIDGE_MESSAGE_TTL_MS = 10_000;

  private static readonly MAX_PENDING_BRIDGE_MESSAGE_COUNT = 100;

  private pendingInjectedBridgeMessages: Array<{
    scope: IInjectedProviderNamesStrings;
    data: unknown;
    targetOrigin: string;
    createdAt: number;
  }> = [];

  private isFlushingPendingInjectedBridgeMessages = false;

  private asyncStorageWriteRequestsInFlight = new Map<string, Promise<void>>();

  private completedAsyncStorageWriteRequestIds: string[] = [];

  private completedAsyncStorageWriteRequestIdSet = new Set<string>();

  private rememberCompletedAsyncStorageWriteRequest(requestId: string) {
    if (this.completedAsyncStorageWriteRequestIdSet.has(requestId)) {
      return;
    }
    this.completedAsyncStorageWriteRequestIdSet.add(requestId);
    this.completedAsyncStorageWriteRequestIds.push(requestId);
    while (
      this.completedAsyncStorageWriteRequestIds.length >
      ASYNC_STORAGE_FORWARDER_COMPLETED_REQUEST_LIMIT
    ) {
      const expiredRequestId =
        this.completedAsyncStorageWriteRequestIds.shift();
      if (expiredRequestId) {
        this.completedAsyncStorageWriteRequestIdSet.delete(expiredRequestId);
      }
    }
  }

  private async runAsyncStorageWriteOnce(
    requestId: string,
    write: () => Promise<void>,
  ) {
    if (this.completedAsyncStorageWriteRequestIdSet.has(requestId)) {
      return;
    }

    const existingRequest =
      this.asyncStorageWriteRequestsInFlight.get(requestId);
    if (existingRequest) {
      await existingRequest;
      return;
    }

    const promise = write()
      .then(() => {
        this.rememberCompletedAsyncStorageWriteRequest(requestId);
      })
      .finally(() => {
        this.asyncStorageWriteRequestsInFlight.delete(requestId);
      });
    this.asyncStorageWriteRequestsInFlight.set(requestId, promise);
    await promise;
  }

  private getAsyncStorageWriteForwarderStatus(requestId: string) {
    return parseAsyncStorageWriteForwarderRequestStatus(
      getAsyncStorageForwarderSharedStore()?.get(
        buildAsyncStorageWriteForwarderStatusKey(requestId),
      ),
    );
  }

  private setAsyncStorageWriteForwarderStatus(
    status: IAsyncStorageWriteForwarderRequestStatus,
  ) {
    getAsyncStorageForwarderSharedStore()?.set(
      buildAsyncStorageWriteForwarderStatusKey(status.requestId),
      serializeAsyncStorageWriteForwarderRequestStatus(status),
    );
  }

  private getNativeBackgroundThreadBridgeRelay() {
    const runtimeGlobal = globalThis as typeof globalThis & {
      __onekeyNativeBackgroundThreadBridgeRelay?: {
        emitAppEventToUi: (payload: {
          eventName: string;
          payload: unknown;
          originNodeId?: string;
        }) => boolean;
        sendBridgeMessageToUi: (payload: {
          channel: 'dapp' | 'webEmbed';
          scope: IInjectedProviderNamesStrings;
          data: unknown;
          targetOrigin?: string;
        }) => boolean;
        getBridgeState: (channel: 'dapp' | 'webEmbed') =>
          | {
              channel: 'dapp' | 'webEmbed';
              connected: boolean;
              origin?: string;
              globalOnMessageEnabled: boolean;
            }
          | undefined;
      };
      __onekeyNativeBackgroundThreadFlushPendingBridgeMessages?: () => void;
    };

    return runtimeGlobal.__onekeyNativeBackgroundThreadBridgeRelay;
  }

  private getNativeBackgroundThreadActiveBridgeState(targetOrigin?: string) {
    const bridgeRelay = this.getNativeBackgroundThreadBridgeRelay();
    if (!bridgeRelay) {
      return undefined;
    }

    const bridgeStates = ['dapp', 'webEmbed']
      .map((channel) =>
        bridgeRelay.getBridgeState(channel as 'dapp' | 'webEmbed'),
      )
      .filter((state) => state?.connected);

    if (!bridgeStates.length) {
      return undefined;
    }

    if (targetOrigin) {
      const matchedBridgeState = bridgeStates.find(
        (state) => state?.origin === targetOrigin,
      );
      if (matchedBridgeState) {
        return matchedBridgeState;
      }
    }

    return bridgeStates[0];
  }

  constructor() {
    this.cycleDepsCheck();
    jotaiBgSync.setBackgroundApi(this as any);
    this.allAtoms = jotaiInit();
    if (process.env.NODE_ENV !== 'production') {
      appGlobals.$$backgroundApi = this as any;
    }
    if (
      platformEnv.isNativeBackgroundThread &&
      platformEnv.enableNativeBackgroundThread
    ) {
      (
        globalThis as typeof globalThis & {
          __onekeyNativeBackgroundThreadFlushPendingBridgeMessages?: () => void;
        }
      ).__onekeyNativeBackgroundThreadFlushPendingBridgeMessages = () => {
        void this.flushPendingInjectedBridgeMessages();
      };
    }
    // this.startDemoNowTimeUpdateInterval();
    // Register the 'background' role transport: fan-out received/emitted
    // events to every foreground. Each foreground inspects originNodeId on
    // arrival and skips its own echoes.
    appEventBus.registerTransports({
      broadcastToForegrounds: ({ type, payload, originNodeId }) => {
        if (
          platformEnv.isNativeBackgroundThread &&
          platformEnv.enableNativeBackgroundThread
        ) {
          this.getNativeBackgroundThreadBridgeRelay()?.emitAppEventToUi({
            eventName: type,
            payload,
            originNodeId,
          });
          return;
        }
        const params: IGlobalEventBusSyncBroadcastParams = {
          $$isFromBgEventBusSyncBroadcast: true,
          type,
          payload,
          originNodeId,
        };
        this.bridgeExtBg?.requestToAllUi({
          method: GLOBAL_EVENT_BUS_SYNC_BROADCAST_METHOD_NAME,
          params,
        });
      },
    });

    // Symmetric counterpart to the Main-side GC trigger in Bootstrap.tsx.
    // On native (Hermes split-runtime), the Main forceGarbageCollection()
    // only reclaims Main's heap — Background services' memoize/socket caches
    // live in this runtime's heap and need a local GC pass after their
    // synchronous `.clear()` handlers run. setTimeout(0) defers GC past the
    // current macrotask so every other listener on this runtime finishes
    // first. On Standalone (web/desktop) and Extension, the native memory-
    // warning event never fires (the shared performance shim is a no-op),
    // so this handler is dormant.
    appEventBus.on(EAppEventBusNames.MemoryPressureWarning, (event) => {
      if (event.level !== 'critical') return;
      setTimeout(() => {
        performance.forceGarbageCollection();
      }, 0);
    });
  }

  allAtoms: Promise<{
    [key: string]: JotaiCrossAtom<any>;
  }>;

  @backgroundMethod()
  async getAtomStates(
    atomNames?: EAtomNames[],
  ): Promise<{ states: IBackgroundAtomStates }> {
    const environment = await travelModeManager.getRuntimeEnvironment();
    if (environment.commands.isBlocked) {
      if (
        atomNames?.some((atomName) => !TRAVEL_MODE_READABLE_ATOMS.has(atomName))
      ) {
        await rejectTravelModeUnknownError();
      }
    }
    const requestedAtomNames = environment.commands.isBlocked
      ? (atomNames ?? [...TRAVEL_MODE_READABLE_ATOMS])
      : atomNames;
    const atoms = await this.allAtoms;
    const atomEntries = requestedAtomNames
      ? requestedAtomNames.map((atomName) => {
          const atom = atoms[atomName];
          if (!atom) {
            throw new OneKeyLocalError(
              `getAtomStates ERROR: atomName not found: ${atomName}`,
            );
          }
          return [atomName, atom] as const;
        })
      : Object.entries(atoms);
    const states: IBackgroundAtomStates = {};
    await Promise.all(
      atomEntries.map(async ([key, value]) => {
        const atomValue = await value.get();
        const atomName = key as EAtomNames;
        states[atomName] = environment.commands.isBlocked
          ? await buildTravelModeAtomState(atomName, atomValue)
          : atomValue;
      }),
    );
    return { states };
  }

  @bindThis()
  @backgroundMethod()
  async setAtomValue(atomName: EAtomNames, value: any) {
    const startedAt = Date.now();
    const environment = await travelModeManager.getRuntimeEnvironment();
    if (
      environment.commands.isBlocked &&
      !TRAVEL_MODE_WRITABLE_ATOMS.has(atomName)
    ) {
      await rejectTravelModeUnknownError();
    }
    if (!isBackgroundApiAtomWritable(atomName)) {
      throw new OneKeyLocalError(
        `setAtomValue ERROR: atom is background-owned: ${atomName}`,
      );
    }
    const atoms = await this.allAtoms;
    const atom = atoms[atomName];
    if (!atom) {
      throw new OneKeyLocalError(
        `setAtomValue ERROR: atomName not found: ${atomName}`,
      );
    }
    try {
      let nextValue = value;
      if (environment.commands.isBlocked) {
        const currentValue = await atom.get();
        if (atomName === EAtomNames.passwordPersistAtom) {
          nextValue = mergeTravelModePasswordPersistWrite({
            persistedValue: buildTravelModePasswordPersistView({
              initialValue: passwordAtomInitialValue,
              persistedValue: currentValue,
            }),
            proposedValue: value,
          });
        } else if (atomName === EAtomNames.settingsPersistAtom) {
          nextValue = mergeTravelModeSettingsPersistWrite({
            persistedValue: buildTravelModeSettingsPersistView({
              initialValue: settingsAtomInitialValue,
              persistedValue: currentValue,
            }),
            proposedValue: value,
          });
        } else if (atomName === EAtomNames.jotaiContextStoreMapAtom) {
          nextValue = buildTravelModeContextStoreMapView(value);
        } else if (atomName === EAtomNames.perpsActiveOrderBookOptionsAtom) {
          nextValue = buildTravelModePerpsOrderBookOptionsView(value);
          if (value !== undefined && nextValue === undefined) {
            await rejectTravelModeUnknownError();
          }
        } else if (atomName === EAtomNames.tradingModeAtom) {
          if (value !== 'perp' && value !== 'spot') {
            await rejectTravelModeUnknownError();
          }
          nextValue = value;
        } else if (TRAVEL_MODE_RESETTABLE_PERPS_ATOMS.has(atomName)) {
          // The native JSON bridge encodes undefined array arguments as null.
          if (value !== undefined && value !== null) {
            await rejectTravelModeUnknownError();
          }
          nextValue = undefined;
        } else {
          nextValue = await buildTravelModePasswordRuntimeState({
            currentValue: currentValue as IPasswordAtom,
            proposedValue: value,
          });
        }
      }
      await atom.set(nextValue);
      const durationMs = Date.now() - startedAt;
      if (durationMs >= 1000) {
        defaultLogger.app.appUpdate.log(
          `[BgSetAtomValue] slow atom=${atomName}, durationMs=${durationMs}, payload=${summarizeSetAtomValuePayload(
            value,
          )}`,
        );
      }
    } catch (error) {
      const durationMs = Date.now() - startedAt;
      defaultLogger.app.appUpdate.log(
        `[BgSetAtomValue] failed atom=${atomName}, durationMs=${durationMs}, payload=${summarizeSetAtomValuePayload(
          value,
        )}, error=${(error as Error)?.message || 'unknown'}`,
      );
      throw error;
    }
  }

  @bindThis()
  @backgroundMethod()
  async updateJotaiContextStoreRegistration(
    update: Parameters<
      typeof updateJotaiContextStoreRegistrationInBackground
    >[0],
  ) {
    return updateJotaiContextStoreRegistrationInBackground(update);
  }

  @backgroundMethod()
  async emitEvent<T extends keyof IAppEventBusPayload>(
    type: T,
    payload: IAppEventBusPayload[T],
    originNodeId?: string,
  ): Promise<boolean> {
    if (!originNodeId) {
      // A bridge regression dropped the sender's nodeId. Don't re-label as
      // BG-originated (which would let the sender skip its own echo and
      // mask the regression silently). Log so the regression is visible
      // and pass through empty so downstream receivers all fire — the
      // sender will then double-fire, which is detectable in dev.
      defaultLogger.app.eventBus.missingOriginNodeId({
        source: 'BackgroundApi.emitEvent',
        eventName: type,
      });
    }
    // Route the foreground-originated event through the bus' inbound handler
    // so that (1) bg listeners fire with isRemote=true, and (2) the event is
    // fanned out to every foreground with the *original* sender's nodeId —
    // the sender then skips its own echo.
    appEventBus.dispatchInboundFromForeground({
      type,
      payload,
      originNodeId: originNodeId ?? '',
    });
    return Promise.resolve(true);
  }

  @backgroundMethod()
  async nativeStorage(request: INativeStorageRequest): Promise<unknown> {
    await travelModeManager.ready;
    if (travelModeManager.isMaskingDataSync() && request.scope === 'recovery') {
      return undefined;
    }
    if (
      request.scope === 'recovery' &&
      request.operation === 'resetMigrationTarget' &&
      request.target === 'jotai'
    ) {
      const { resetNativeJotaiStorageAfterMigrationMismatch } =
        await import('../states/jotai/jotaiStorage');
      await resetNativeJotaiStorageAfterMigrationMismatch();
      this.allAtoms = jotaiInit();
      await this.allAtoms;
      return undefined;
    }
    if (request.scope === 'bootstrap') {
      // Bootstrap does not release the UI until Jotai's separate legacy
      // namespace and the general app-storage namespace are both migrated.
      try {
        await this.allAtoms;
      } catch {
        this.allAtoms = jotaiInit();
        await this.allAtoms;
      }
    }
    const { executeNativeStorageRequest } =
      await import('@onekeyhq/shared/src/storage/nativeStorageExecutor');
    return executeNativeStorageRequest(request);
  }

  @backgroundMethod()
  async writeAsyncStorage(request: IAsyncStorageWriteRequest): Promise<void> {
    const environment = await travelModeManager.getRuntimeEnvironment();
    if (environment.persistence.kind === 'masked') {
      return;
    }
    const startedAt = Date.now();
    const summary = getAsyncStorageWriteRequestSummary(request);
    try {
      if (
        this.getAsyncStorageWriteForwarderStatus(request.requestId)?.status ===
        'committed'
      ) {
        return;
      }
      await this.runAsyncStorageWriteOnce(request.requestId, async () => {
        const pendingStatus = this.getAsyncStorageWriteForwarderStatus(
          request.requestId,
        );
        if (pendingStatus?.status === 'committed') {
          return;
        }
        if (pendingStatus) {
          this.setAsyncStorageWriteForwarderStatus({
            ...pendingStatus,
            status: 'executing',
            ts: Date.now(),
          });
        }

        const { default: appStorage } =
          await import('@onekeyhq/shared/src/storage/appStorage');

        switch (request.method) {
          case 'clear':
            await appStorage.clear();
            break;
          case 'multiSet':
            await appStorage.multiSet(request.args[0]);
            break;
          case 'multiRemove':
            await appStorage.multiRemove(request.args[0]);
            break;
          case 'multiMerge':
            await appStorage.multiMerge(request.args[0]);
            break;
          default: {
            const unsupportedRequest: never = request;
            throw new OneKeyLocalError(
              `Unsupported AsyncStorage write request: ${String(unsupportedRequest)}`,
            );
          }
        }

        if (pendingStatus) {
          this.setAsyncStorageWriteForwarderStatus({
            ...pendingStatus,
            status: 'committed',
            ts: Date.now(),
          });
        }
      });
    } catch (error) {
      asyncStorageForwarderBgLog('write-error', {
        ...summary,
        durationMs: Date.now() - startedAt,
        errorMessage: (error as Error)?.message || 'unknown',
      });
      throw error;
    }
  }

  cycleDepsCheck() {
    //
  }

  bridge: JsBridgeBase | null = null;

  webEmbedBridge: JsBridgeBase | null = null;

  bridgeExtBg: JsBridgeExtBackground | null = null;

  // Only $private is eager here; per-chain providers are loaded lazily on first
  // use via getProviderApi() so their heavy chain SDKs stay out of the initial
  // (web) / startup (native) bundle graph.
  providers: Partial<Record<IInjectedProviderNames, ProviderApiBase>> =
    createBackgroundProviders({
      backgroundApi: this,
    });

  // In-flight loader cache: dedupes concurrent loads of the same provider so two
  // simultaneous dapp messages can't construct two ProviderApi instances.
  private providerApiLoadingCache: Partial<
    Record<IInjectedProviderNames, Promise<ProviderApiBase>>
  > = {};

  async getProviderApi(
    scope: IInjectedProviderNames,
  ): Promise<ProviderApiBase> {
    const existing = this.providers[scope];
    if (existing) {
      return existing;
    }
    let loading = this.providerApiLoadingCache[scope];
    if (!loading) {
      const loader = providerApiLoaders[scope];
      if (!loader) {
        throw new OneKeyLocalError(
          `[${scope as string}] ProviderApi loader is not found.`,
        );
      }
      loading = loader()
        .then((module) => {
          const ProviderApiClass = module.default;
          const instance = new ProviderApiClass({ backgroundApi: this });
          this.providers[scope] = instance;
          return instance;
        })
        .catch((error) => {
          // Drop the rejected promise so a transient load failure (e.g. a
          // failed webpack chunk request on web) doesn't permanently poison
          // the cache and leave the provider unavailable for the session.
          delete this.providerApiLoadingCache[scope];
          throw error;
        });
      this.providerApiLoadingCache[scope] = loading;
    }
    return loading;
  }

  // @ts-ignore
  _persistorUnsubscribe: () => void;

  connectBridge(bridge: JsBridgeBase | null) {
    if (platformEnv.isExtension) {
      this.bridgeExtBg = bridge as unknown as JsBridgeExtBackground | null;
    }
    this.bridge = bridge;
    if (bridge) {
      void this.flushPendingInjectedBridgeMessages();
    }
  }

  connectWebEmbedBridge(bridge: JsBridgeBase | null) {
    defaultLogger.app.webembed.webEmbedBgConnectWebEmbedBridge({
      hasBridge: !!bridge,
    });
    this.webEmbedBridge = bridge;
    if (bridge) {
      void this.flushPendingInjectedBridgeMessages();
    }
  }

  protected rpcResult(
    result: any,
    rpcRequest?: IJsonRpcRequest,
  ): IJsonRpcResponse<any> {
    return {
      id: rpcRequest?.id ?? undefined,
      jsonrpc: rpcRequest?.jsonrpc ?? '2.0',
      result,
    };
  }

  async handleProviderMethods(
    payload: IJsBridgeMessagePayload,
  ): Promise<IJsonRpcResponse<any>> {
    return travelModeDappRequestIngress.run({
      onBlocked: () => {
        throw web3Errors.rpc.internal('Unknown error');
      },
      operation: async () => {
        const { scope, origin } = payload;
        const payloadData = payload?.data as IJsonRpcRequest;
        const provider: ProviderApiBase = await this.getProviderApi(
          scope as IInjectedProviderNames,
        );
        if (
          scope === IInjectedProviderNames.$private &&
          isProviderApiPrivateOriginDenied({
            method: payloadData?.method,
            origin,
          })
        ) {
          const error = new Error(
            `[${origin as string}] is not allowed to call $private methods: ${
              payloadData?.method
            }`,
          );
          throw error;
        }
        // throw web3Errors.provider.custom({
        //   code: 3881,
        //   message: 'test custom error to dapp',
        // });
        const result = await provider.handleMethods(payload);
        ensureSerializable(result);
        // TODO non rpc result return in some chain provider
        const resultWrapped = this.rpcResult(result, payloadData);

        return resultWrapped;
      },
    });
  }

  async _bridgeReceiveHandler(payload: IJsBridgeMessagePayload): Promise<any> {
    const { scope, origin, internal } = payload;
    const request = (payload.data ?? {}) as IJsonRpcRequest;
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    const { method, params } = request;

    if (!origin) {
      throw new OneKeyLocalError('BackgroundApi [payload.origin] is required.');
    }

    if (!internal && !scope) {
      throw new OneKeyLocalError(
        'BackgroundApi [payload.scope] is required for non-internal method call.',
      );
    }

    if (scope) {
      return this.handleProviderMethods(payload);
    }

    // call background global methods (backgroundDappTest.ts)
    //    Only Extension and internal call allowed
    if (isExtensionInternalCall(payload)) {
      return this.handleInternalMethods(payload);
    }

    if (isProviderApiPrivateAllowedOrigin(origin)) {
      return this.handleSelfOriginMethods(payload);
    }

    throwMethodNotFound(method);
  }

  bridgeReceiveHandler: IJsBridgeReceiveHandler = async (
    payload: IJsBridgeMessagePayload,
  ): Promise<any> => {
    const res = await this._bridgeReceiveHandler(payload);
    return res;
  };

  handleSelfOriginMethods(payload: IJsBridgeMessagePayload) {
    // TODO open webview url
    console.log(payload);
  }

  // eslint-disable-next-line @typescript-eslint/require-await
  async handleInternalMethods(payload: IJsBridgeMessagePayload): Promise<any> {
    const { method, params, service } = (payload.data ??
      {}) as IBackgroundApiInternalCallMessage;
    const serviceName = service || '';
    const paramsArr = [].concat(params as any);

    return travelModeCommandDispatcher.runServiceCall({
      methodName: method,
      serviceName,
      operation: async () => {
        const serviceApi = getBackgroundServiceApi({
          serviceName,
          backgroundApi: this,
        });

        const methodFunc = serviceApi[method];
        if (methodFunc) {
          const resultPromise = methodFunc.call(serviceApi, ...paramsArr);
          ensurePromiseObject(resultPromise, {
            serviceName,
            methodName: method,
          });
          const result = await resultPromise;
          ensureSerializable(result);
          // eslint-disable-next-line @typescript-eslint/no-unsafe-return
          return result;
        }

        throwMethodNotFound(serviceName, method);
      },
    });
  }

  sendForProviderMaps: Record<string, any> = {};

  sendForProvider(providerName: IInjectedProviderNamesStrings): any {
    if (!providerName) {
      throw new OneKeyLocalError('sendForProvider: providerName is required.');
    }
    if (!this.sendForProviderMaps[providerName]) {
      this.sendForProviderMaps[providerName] =
        this.sendMessagesToInjectedBridge.bind(this, providerName);
    }
    return this.sendForProviderMaps[providerName];
  }

  sendMessagesToInjectedBridge = async (
    scope: IInjectedProviderNamesStrings,
    data: unknown,
    targetOrigin: string,
  ) => {
    const delivered = await this.trySendMessagesToInjectedBridge({
      scope,
      data,
      targetOrigin,
    });

    if (!delivered) {
      this.enqueuePendingInjectedBridgeMessage({
        scope,
        data,
        targetOrigin,
      });
    }
  };

  private prunePendingInjectedBridgeMessages() {
    const now = Date.now();
    this.pendingInjectedBridgeMessages =
      this.pendingInjectedBridgeMessages.filter(
        (message) =>
          now - message.createdAt <=
          BackgroundApiBase.PENDING_BRIDGE_MESSAGE_TTL_MS,
      );
  }

  private enqueuePendingInjectedBridgeMessage(params: {
    scope: IInjectedProviderNamesStrings;
    data: unknown;
    targetOrigin: string;
  }) {
    this.prunePendingInjectedBridgeMessages();
    this.pendingInjectedBridgeMessages.push({
      ...params,
      createdAt: Date.now(),
    });

    if (
      this.pendingInjectedBridgeMessages.length >
      BackgroundApiBase.MAX_PENDING_BRIDGE_MESSAGE_COUNT
    ) {
      this.pendingInjectedBridgeMessages.shift();
    }
  }

  private async resolveBridgeMessageData(params: {
    data: unknown;
    origin: string;
  }) {
    let { data } = params;
    if (isFunction(data)) {
      data = await data({ origin: params.origin });
    }
    ensureSerializable(data);
    return data;
  }

  private async trySendMessagesToInjectedBridge(params: {
    scope: IInjectedProviderNamesStrings;
    data: unknown;
    targetOrigin: string;
  }) {
    const { scope, targetOrigin } = params;
    let { data } = params;

    if (
      platformEnv.isNativeBackgroundThread &&
      platformEnv.enableNativeBackgroundThread
    ) {
      const bridgeRelay = this.getNativeBackgroundThreadBridgeRelay();
      const bridgeState =
        this.getNativeBackgroundThreadActiveBridgeState(targetOrigin);
      if (!bridgeRelay || !bridgeState || !bridgeState.globalOnMessageEnabled) {
        return false;
      }

      data = await this.resolveBridgeMessageData({
        data,
        origin: bridgeState.origin || targetOrigin,
      });
      const delivered = bridgeRelay.sendBridgeMessageToUi({
        channel: bridgeState.channel,
        scope,
        data,
        targetOrigin,
      });
      return delivered;
    }

    if (platformEnv.isExtension) {
      const currentSettings = await settingsPersistAtom.get();
      let requestTargetOrigin = targetOrigin;
      if (
        currentSettings.alignPrimaryAccountMode ===
        EAlignPrimaryAccountMode.AlwaysUsePrimaryAccount
      ) {
        requestTargetOrigin = consts.ONEKEY_REQUEST_TO_ALL_CS;
      }
      this.bridgeExtBg?.requestToAllCS(scope, data, requestTargetOrigin);
      return true;
    }

    let delivered = false;
    const bridges = [this.bridge, this.webEmbedBridge].filter(
      (bridge): bridge is JsBridgeBase => Boolean(bridge),
    );

    for (const bridge of bridges) {
      const bridgeOrigin = bridge.remoteInfo?.origin;
      const shouldSend =
        Boolean(bridgeOrigin) &&
        (!targetOrigin || targetOrigin === bridgeOrigin) &&
        bridge.globalOnMessageEnabled;
      if (shouldSend && bridgeOrigin) {
        const payload = await this.resolveBridgeMessageData({
          data,
          origin: bridgeOrigin,
        });
        bridge.requestSync({ scope, data: payload });
        delivered = true;
      }
    }

    return delivered;
  }

  private async flushPendingInjectedBridgeMessages() {
    if (this.isFlushingPendingInjectedBridgeMessages) {
      return;
    }

    this.isFlushingPendingInjectedBridgeMessages = true;
    try {
      this.prunePendingInjectedBridgeMessages();
      const pendingMessages = this.pendingInjectedBridgeMessages.splice(0);
      const undeliveredMessages: typeof pendingMessages = [];

      for (const message of pendingMessages) {
        const delivered = await this.trySendMessagesToInjectedBridge(message);
        if (!delivered) {
          undeliveredMessages.push(message);
        }
      }

      this.pendingInjectedBridgeMessages.unshift(...undeliveredMessages);
      this.prunePendingInjectedBridgeMessages();
    } finally {
      this.isFlushingPendingInjectedBridgeMessages = false;
    }
  }
}
export default BackgroundApiBase;
